export function routeDomain(path: string): string {
  const seg = path.replace(/^\/api\//, "").split("/")[0] ?? "";
  return seg;
}

export function domainLabel(domain: string): string {
  return DOMAIN_LABELS[domain] ?? domain;
}

/** "GetWorkspaceAgentActivity30d" -> "Get workspace agent activity 30d" */
export function handlerLabel(handler: string): string {
  return handler
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .replace(/^./, (c) => c.toUpperCase());
}

/** Endpoints that mutate daemon/executor state; hidden unless explicitly enabled. */
export function isInternalRoute(path: string): boolean {
  return path.startsWith("/api/daemon") || path.startsWith("/api/internal");
}

/** Public/auth surfaces the PAT proxy never calls. */
export function isBlockedRoute(path: string): boolean {
  return (
    path.startsWith("/api/auth") ||
    path.startsWith("/auth") ||
    path.startsWith("/ws") ||
    path.startsWith("/hooks") ||
    path.startsWith("/plugin-surfaces")
  );
}

const MATCHERS = API_ROUTES.map(
  (route) =>
    [
      route[0],
      new RegExp("^" + route[1].replace(/\{[^/]+\}/g, "[^/]+") + "$"),
      route,
    ] as const,
);

export function findRoute(method: string, path: string): ApiRouteTuple | null {
  const upper = method.toUpperCase();
  for (const [routeMethod, pattern, route] of MATCHERS) {
    if (routeMethod === upper && pattern.test(path)) return route;
  }
  return null;
}

export function routeMatches(method: string, path: string): boolean {
  return findRoute(method, path) !== null;
}

export const ROUTE_COUNT = API_ROUTES.length;
